(37763, 5, 0, 'koKR', 'Odbierz miecz, $N, i zanieś go przez ten portal do Dalaranu. Vereesa Bieżywiatr będzie tam czekać, by ci pogratulować.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(24423, 'koKR', '', 'Cień w sukurs ogniowi!', 0),
(24424, 'koKR', '', 'Sacrolash kieruje Rozbłysk cienia na $n.', 0),
(24426, 'koKR', '', 'Alythess kieruje Pożar na $n.', 0),
(24452, 'koKR', '', 'Alythess! Twój ogień płonie we mnie!', 0),
(24983, 'koKR', 'Sathrovarr doprowadza Kalegosa do szaleńczej furii!', '', 0),
(25050, 'koKR', '', 'Dawać tu chochliki!', 0),
(25200, 'koKR', 'Jednostka przechodzi w tryb oszczędzania energii.', '', 0),
(25201, 'koKR', 'Wykryto zagrożenie w pobliżu. Wyjście z trybu oszczędzania energii.', '', 0),
(25202, 'koKR', 'Wrogowie w zasięgu wzroku! Atakujcie, a ja spróbuję uruchomić Obrońcę!', 'Wrogowie w zasięgu wzroku! Atakujcie, a ja spróbuję uruchomić Obrońcę!', 0),
(25203, 'koKR', 'Wykryto obecność wroga.', '', 0),
(25206, 'koKR', 'Jednostka sprawna i atakuje cele.', '', 0),
(25220, 'koKR', 'Chodźcie, spróbujcie szczęścia!', '', 0),
(25221, 'koKR', '', 'Stójcie, przyjaciele! Zanim ten diabeł spotka swój los, można się od niego czegoś dowiedzieć!', 0),
(25222, 'koKR', 'Marna jaszczurko! Jedyna odpowiedź, jaką tu znajdziesz, to śmierć!', '', 0),
(25223, 'koKR', 'Ba! Twoja magia jest słaba!', '', 0),
(25226, 'koKR', '', 'Gdzie jest Anveena, demonie? Co się stało z Kalecem?', 0),
(25227, 'koKR', '', 'Powiesz mi, gdzie są!', 0),
(25228, 'koKR', '', 'Mów! Mam dość pytania!', 0),
(25229, 'koKR', '', 'Malygosie, mój panie... zrobiłam... co mogłam.', 0),
(25263, 'koKR', 'Jestem twoim dłużnikiem na zawsze. Kiedy zatriumfujemy nad Kil\'jaedenem, cały ten świat również będzie twoim dłużnikiem.', '', 0),
(25482, 'koKR', 'Intruzi! Nie wpuśćcie ich do Sanktuarium!', '', 0),
(25496, 'koKR', 'Aaagh! Już nigdy nie będę niewolnikiem Malygosa! Rzućcie mi wyzwanie, a zostaniecie zniszczeni!', '', 0),
(25497, 'koKR', 'Oczyszczę was!', '', 0),
(25498, 'koKR', 'Wasz ból dopiero się zaczął!', '', 0),
(25499, 'koKR', 'W imię Kil\'jaedena!', '', 0),
(25500, 'koKR', 'Ostrzegałem was!', '', 0),
(25502, 'koKR', 'Kil\'jaeden musi zostać zniszczony!', '', 0),
(25513, 'koKR', '', 'Ogień w sukurs cieniowi!', 0),
(25514, 'koKR', '', 'Płomienie pochłaniają.', 0),
(25515, 'koKR', '', 'Edir harach!', 0),
(25516, 'koKR', '', 'Sacrolash!', 0),
(25517, 'koKR', '', 'Szczęście właśnie cię opuściło!', 0),
(25518, 'koKR', '', 'Der\'ek... manul.', 0),
(25519, 'koKR', '', 'Cienie pochłaniają.', 0),
(25520, 'koKR', '', 'Ee-nok Kryul!', 0),
(25521, 'koKR', '', 'Czas to luksus, na który już cię nie stać!', 0),
(25522, 'koKR', '', 'Ja... gasnę.', 0),
(25523, 'koKR', '', 'Cieszę się, że tu jesteś, $N. Sytuacja militarna na Płaskowyżu Słonecznej Studni jest dość ponura.', 0),
(25524, 'koKR', 'Złóż mi raport o sytuacji, kapitanie.', 'Złóż mi raport o sytuacji, kapitanie.', 0),
(25525, 'koKR', '', 'Ofensywa Straceńczego Słońca poczyniła wielkie postępy na obrzeżach Wyspy Quel\'Danas. Siły Kil\'jaedena są spychane, a w tym chaosie udało mi się poprowadzić tutaj, na Płaskowyż Słonecznej Studni, niewielki oddział zwiadowczy. Moi żołnierze przeszli przez Plac Parhelium, dostrzegli grupę krwawych elfów ze Słonecznego Ostrza i wtedy starliśmy się z wrogiem. Ta walka szybko zamieniła się w katastrofę.', 0),
(25526, 'koKR', 'Co poszło nie tak?', 'Co poszło nie tak?', 0),
(25527, 'koKR', '', 'Obrońcy Kil\'jaedena tutaj, na Płaskowyżu Słonecznej Studni, są znacznie silniejsi od wszystkiego, z czym mierzyliśmy się na zewnątrz, na wyspie. Legion wypaczył nawet naszą technologię Tajemnych strażników energią spaczenia, tworząc coś znacznie groźniejszego. Jeden jedyny Obrońca Słonecznego Ostrza zdziesiątkował moich żołnierzy, więc rozkazałam szybki odwrót. Spodziewałam się, że mój oddział zostanie całkiem zepchnięty z płaskowyżu, ale wróg zaskoczył mnie i przerwał pościg.', 0),
(25528, 'koKR', 'Dlaczego przestali?', 'Dlaczego przestali?', 0),
(25529, 'koKR', '', 'Nie wiem, ale cieszę się, że tak się stało. Dzięki tej chwili wytchnienia Anachoreta Elbadon zdołał ocalić wielu podległych mi mężczyzn i kobiet. Wysłałam naprzód kilku moich najbardziej skrytych zwiadowców i przynieśli ciekawe wieści. Niemal wszyscy Obrońcy Słonecznego Ostrza są wyłączeni! Wygląda na to, że siły Kil\'jaedena oszczędzają energię i zadowalają się powstrzymywaniem nas jednym aktywnym Obrońcą. Jeśli ty i twoi towarzysze chcecie wedrzeć się do środka, pozwól, że zaproponuję plan ataku.', 0),
(25530, 'koKR', 'Dziękuję za twoje spostrzeżenia.', 'Dziękuję za twoje spostrzeżenia.', 0),
(25531, 'koKR', '', 'Wykorzystajcie to, że ich Obrońcy Słonecznego Ostrza są wyłączeni. Jeśli dostrzeże was któryś z ich zwiadowców Słonecznego Ostrza, ten elf na pewno spróbuje ponownie uruchomić pobliskiego Obrońcę. Zabijcie go szybko, żeby temu zapobiec. Gdy krwawe elfy zostaną wyeliminowane, a wy nie uruchomicie czujników zbliżeniowych Obrońcy, powinniście przejść obok bez walki. Oszczędzicie w ten sposób i czas, i siły.', 0),
(25532, 'koKR', 'Kapitan Selana poleciła mi wspierać wasze wysiłki tutaj, na Płaskowyżu Słonecznej Studni.', '', 0),
(25533, 'koKR', 'Jaki jest obecny stan bram Słonecznej Studni?', 'Jaki jest obecny stan bram Słonecznej Studni?', 0),
(25534, 'koKR', 'Agamath, Pierwsza Brama, została przełamana. Dwie z najpotężniejszych poruczniczek Kil\'jaedena, Lady Sacrolash i Wielka Czarnoksiężniczka Alythess, są teraz podatne na atak.', '', 0),
(25535, 'koKR', 'Wszystkie trzy bariery działają w pełni. Porozmawiaj z arcymagiem Ne\'thulem w Porcie Słonecznego Zasięgu, żeby pomóc w otwarciu bram.', '', 0),
(25536, 'koKR', 'Agamath, Pierwsza Brama, i Rohendor, Druga Brama, zostały zniszczone. Pozostał tylko Archonisus, Trzecia Brama.', '', 0),
(25537, 'koKR', 'Wszystkie bariery blokujące wam drogę do Słonecznej Studni zostały zniszczone. Wejdźcie do Słonecznej Studni i powstrzymajcie Kil\'jaedena przed wkroczeniem do tego świata!', '', 0),
(25538, 'koKR', 'Teraz, gdy Kalegos jest wolny, czy możesz mnie teleportować do Punktu Szczytowego?', 'Teraz, gdy Kalegos jest wolny, czy możesz mnie teleportować do Punktu Szczytowego?', 0),
(25539, 'koKR', 'Lady Sacrolash i Wielka Czarnoksiężniczka Alythess zostały pokonane. Czy możesz mnie teleportować do Sanktuarium Wiedźmy?', 'Lady Sacrolash i Wielka Czarnoksiężniczka Alythess zostały pokonane. Czy możesz mnie teleportować do Sanktuarium Wiedźmy?', 0),
(25540, 'koKR', 'Utorowaliśmy drogę do Kil\'jaedena! Czy możesz mnie przenieść w pobliże Słonecznej Studni?', 'Utorowaliśmy drogę do Kil\'jaedena! Czy możesz mnie przenieść w pobliże Słonecznej Studni?', 0),
(25544, 'koKR', 'Wszystkie moje plany prowadziły do tej chwili!', '', 0),
(25545, 'koKR', 'Trzymajcie się zadania, nie traćcie czasu!', '', 0),
(25546, 'koKR', 'Dość się naczekałem!', '', 0),
(25547, 'koKR', 'Zawiedźcie mnie, a będziecie cierpieć przez wieczność!', '', 0),
(25548, 'koKR', 'Wyssijcie dziewczynę! Wysysajcie jej moc, aż zostanie z niej pusta skorupa!', '', 0),
(25628, 'koKR', 'Ach, kolejne owieczki na rzeź!', '', 0),
(25629, 'koKR', 'Giń, insekcie!', '', 0),
(25630, 'koKR', 'Jesteś mięsem!', '', 0),
(25631, 'koKR', 'Zbyt łatwe!', '', 0),
(25632, 'koKR', 'Chodźcie tu i walczcie!', '', 0),
(25633, 'koKR', 'Kolejny dzień, kolejna chwalebna bitwa!', '', 0),
(25634, 'koKR', 'Dla tego żyję!', '', 0),
(25635, 'koKR', 'Tyle z prawdziwego wyzwania. Giń!', '', 0),
(25636, 'koKR', 'Aaagh! Brawo! Teraz robi się... ciekawie...', '', 0),
(37441, 'koKR', 'Czy to naprawdę może być Quel\'Delar?', '', 0),
(37442, 'koKR', 'Zobaczymy.', '', 0),
(37444, 'koKR', 'Spójrz na niego, Lor\'themarze. To z pewnością Quel\'Delar.', '', 0),
(37449, 'koKR', 'To rzeczywiście Quel\'Delar. Nie sądziłem, że dożyję dnia, w którym legendarny miecz Thaloriena Szukającego Świtu zostanie nam zwrócony.', '', 0),
(37450, 'koKR', 'Jesteś $gbohaterem:bohaterką; i natchnieniem dla sin\'dorei, $n, symbolem naszej wytrwałości w obliczu tragedii i zdrady.', '', 0),
(37451, 'koKR', 'Regent mówi prawdę, $n. Poświęcenie Thaloriena nie zdołało zapobiec upadkowi tej właśnie Słonecznej Studni.', '', 0),
(37452, 'koKR', 'Kiedy $gznalazłeś:znalazłaś; ten miecz, był złamany i porzucony, tak jak Srebrna Luna po zdradzie Kael\'thasa.', '', 0),
(37453, 'koKR', 'Niech Quel\'Delar będzie znakiem, że nigdy się nie poddamy, że stawimy czoła każdemu wrogowi bez strachu.', '', 0),
(37454, 'koKR', 'Nie tylko sin\'dorei darzą Quel\'Delar wielkim szacunkiem. Ma on miejsce w sercach wszystkich dzieci Srebrnej Luny.', '', 0),
(37455, 'koKR', 'To ostrze zostało nam zwrócone nie bez powodu, panowie. Nadszedł czas, by zjednoczyć się za posiadaczem Quel\'Delara i pomścić zniszczenie Srebrnej Luny i Słonecznej Studni.', '', 0),
(37456, 'koKR', 'Odbierz miecz, $n, i zanieś go przez ten portal do Dalaranu. Arcymag Aethas Słońcobójca będzie tam czekać, by ci pogratulować.', '', 0),
(37820, 'koKR', 'Panie i panowie, przedstawiam $gposiadacza:posiadaczkę; Quel\'Delara: $n.', '', 0),
(44549, 'koKR', 'Chaos...', '', 0),
(46444, 'koKR', 'To było zabawne.', '', 0);
